import{z as A,x as p,o as i,c as s,q as r,j as E,D as t,d as l,s as d,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"端云协同","description":"","frontmatter":{"title":"端云协同","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/edge-cloud-split.md","filePath":"llm/edge-cloud-split.md","lastUpdated":1791413859000}'),B={name:"llm/edge-cloud-split.md"};function c(m,e,f,u,C,V){const o=p("Mermaid");return i(),s("div",null,[e[2]||(e[2]=r('<h1 id="端云协同" tabindex="-1">端云协同 <a class="header-anchor" href="#端云协同" aria-label="Permalink to &quot;端云协同&quot;">​</a></h1><div class="epigraph"><p>把 prefill 放在算力型机器上、decode 放在带宽型或端侧，是同一条屋顶线在空间上的拆分；切错阶段，两边都付全价。</p><footer>—— Patel et al., Splitwise：生成式 LLM 推理的阶段拆分；端侧切分的古典对照见 Kang et al., Neurosurgeon, ASPLOS 2017</footer></div><p><a href="/llm/cpu-inference-quant">上一课</a>表明端侧能跑小模型逐步。云侧有 HBM 与连续批。本课把请求切开：哪一段在端、哪一段在云。Splitwise 在数据中心内拆 prefill/decode 机器；Neurosurgeon 更早把 DNN 层切到端云。LLM 的合法切点是阶段（prefill vs decode）、层（浅层在端）、或草稿/目标（投机）。切点必须对齐 KV 传输：若云做完 prefill 把 KV 送到端上 decode，传输体积是 \\(\\mathrm{KV}(n_{\\mathrm{prompt}})\\)，可能比再跑一遍小模型 prefill 更贵。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>端侧弱在 prefill 二次项与大权重；云贵在 decode 占用 HBM 槽位的时间。直觉「云做难题、端做简单」没有定义切点。缺口是：传输的是 token、KV，还是层激活。传 token 最轻，等于普通 API。传 KV 能让端接着 decode，但 KV 体积按公式线性于 \\(n\\)，长提示上是炸弹。传激活切层，要层间形状契约，类似流水线并行，延迟加 RTT。</p><p>隐私：端上 prefill 本地数据、只把非敏感摘要送云，是产品切分，不是性能切分。两者常被混谈，必须分开写 SLA 与威胁模型。<span class="marginnote">prefill 与 decode 可以记成「读题」与「答题」：prefill 把整段提示一次性算完，算力密集、能大批并行；decode 一个 token 一个 token 往外蹦，每步都要搬全部权重和 KV，受内存带宽限制。切分的思想就是让读题去算力强的机器、答题去带宽强或离用户近的机器。</span></p><p><span class="marginnote">RTT 对 decode 逐步不可接受（每 token 一次云往返）。端云协同若把逐步留在云，端只是瘦客户端；若逐步留在端，云只能帮忙 prefill 或草稿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种可组合方案：（1）云 prefill，KV 不下发，端只显示流——即普通服务；（2）云 prefill，下发 KV，端 decode——只在 \\(n_{\\mathrm{prompt}}\\) 小、KV 量化后体积小于再计算时；（3）端上小模型全程，云只在难例升级——路由。投机是（3）的精细版，下一课专写。Splitwise 是云内（1）的机器分型：prefill 池买算力卡，decode 池买显存带宽卡，用 KV 在高速互连上搬——数据中心内才划算。</p>',9)),(i(),E(n,null,{default:t(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20CUT%7B%22%E5%88%87%E7%82%B9%22%7D%0A%20%20CUT%20--%3E%20A%5B%22%E5%8F%AA%E4%BC%A0%20token%3A%20%E6%99%AE%E9%80%9A%20API%22%5D%0A%20%20CUT%20--%3E%20B%5B%22%E4%BC%A0%20KV%3A%20%E4%BA%91%20prefill%20%E7%AB%AF%20decode%22%5D%0A%20%20CUT%20--%3E%20C%5B%22%E7%AB%AF%E5%B0%8F%E6%A8%A1%E5%9E%8B%20%2B%20%E4%BA%91%E5%8D%87%E7%BA%A7%22%5D%0A%20%20B%20--%3E%20VOL%5B%22KV%20%E4%BD%93%E7%A7%AF%20vs%20RTT%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,[l("成本模型：云 decode 占用槽位的时间贵；端 decode 电与延迟受 DRAM 限制。最优切分随 \\(n\\)、\\(N\\)、是否长思维链变。长思维链在端上会先撞容量；应云侧 decode 或缩短链。视觉编码可留端（隐私）或留云（算力），见"),a("a",{href:"/llm/vision-encoder-pipeline"},"视觉流水"),l("。")],-1)),e[5]||(e[5]=a("p",null,"「云 prefill 完端上接 decode」这条方案，值不值得走要过两道闸：",-1)),(i(),E(n,null,{default:t(()=>[d(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLAN%5B%22%E4%BA%91%20prefill%20%E5%AE%8C%EF%BC%8C%E7%AB%AF%E8%A6%81%E4%B8%8D%E8%A6%81%E6%8E%A5%20decode%22%5D%20--%3E%20Q%7B%22%E6%8F%90%E7%A4%BA%E7%9F%AD%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E9%95%BF%EF%BC%9A%E4%B8%8A%E4%B8%87%20token%22%7C%20NO%5B%22%E4%B8%8D%E4%B8%8B%E5%8F%91%EF%BC%9A%E6%BB%A1%20KV%20%E6%98%AF%E4%BD%93%E7%A7%AF%E7%82%B8%E5%BC%B9%22%5D%0A%20%20Q%20--%3E%7C%22%E7%9F%AD%22%7C%20Q2%7B%22KV%20%E9%87%8F%E5%8C%96%E5%90%8E%E4%BD%93%E7%A7%AF%20%5Clt%20%E7%AB%AF%E9%87%8D%E7%AE%97%20prefill%20%E7%9A%84%E4%BB%A3%E4%BB%B7%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20YES%5B%22%E4%B8%8B%E5%8F%91%20KV%EF%BC%9A%E7%AB%AF%E4%B8%8A%20decode%22%5D%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20RE%5B%22%E4%B8%8D%E4%B8%8B%E5%8F%91%EF%BC%9A%E7%AB%AF%E9%87%8D%E7%AE%97%E6%88%96%E7%95%99%E5%9C%A8%E4%BA%91%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=r('<p><span class="marginnote">KV 有多大？以 8B 级模型、16K 上下文为例，FP16 未量化的 KV cache 约 2 GB，比很多人想的重得多；压到 4-bit 也还有几百 MB，移动网络上传仍是数十秒级。所以「下发 KV」只在短提示、且量化后体积确实小于端上重算时才划算——这正是决策树第二道闸的存在理由。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要为长文档下发满 KV。不要逐步 token 往返云。安全：KV 含提示信息，下发等于泄漏上下文。<span class="marginnote">为什么隐私切分和性能切分不能混着谈？性能切分的目标是延迟与成本，SLA 按毫秒计；隐私切分的目标是数据不出端，威胁模型按「谁能看到什么」计。混在一起设计，最容易出「为了性能把敏感 KV 下发到云」的事故——性能指标变好看了，隐私承诺却破了，这两本账必须分开立。</span>下一课：端侧投机——用本地草稿减云上目标的逐步次数。</p><p>出处：Patel et al., Splitwise；Kang et al., ASPLOS 2017。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>切的是阶段、层或草稿/目标；逐步不能每 token 往返。</li><li>下发 KV 只在体积小于再计算且 \\(n\\) 小时。</li><li>云内 Splitwise 用高速互连搬 KV，端云 RTT 不成立同一假设。</li><li>隐私切分与性能切分分开设计。</li><li>长思维链倾向留云或缩短。</li><li>下一课：端侧投机解码。</li><li>出处：Patel et al., Splitwise；Kang et al., 2017。</li></ul>',6))])}const F=A(B,[["render",c]]);export{D as __pageData,F as default};
